            continue
        if params.get('since') is not None and r['created'] < params['since']:
            continue
        out.append(r)
    out.sort(key=lambda r: r['id'])
    buf = io.StringIO()
    w = csv.writer(buf, lineterminator='\n')
    w.writerow(['id', 'title', 'owner', 'amount'])
    for r in out:
        w.writerow([int(r['id']), r['title'], r['owner'], r['amount']])
